arguments.source:
func normalizeKind(kind string) string {
	return strings.ToLower(strings.TrimSpace(kind))
}

type deliverySink struct {
	sink Sink
}

func NewDeliverySink(sink Sink) Sink {
	return deliverySink{sink: sink}
}

func (d deliverySink) Write(event Event) error {
	event.Kind = normalizeKind(event.Kind)
	return d.sink.Write(event)
}

arguments.body:
switch normalizeKind(kind) {
case "health", "probe":
	return "control"
default:
	return "data"
}

delivery := audit.NewDeliverySink(sink)
for _, event := range events {
	if err := delivery.Write(event); err != nil {
		return err
	}
}
return nil

